-- P8867 [NOIP2022] 建造军营
select public.admin_publish_column($json$
{
  "mode": "insert",
  "column_key": "sub-admin-p8867-barrack",
  "author_name": "Xesir",
  "column_name": "P8867 [NOIP2022] 建造军营",
  "content": "## 题目描述\n\nA 国与 B 国正在激烈交战中，A 国打算在自己的国土上建造一些军营。\n\nA 国的国土由 $n$ 座城市组成，$m$ 条双向道路连接这些城市，使得**任意两座城市均可通过道路直接或间接到达**。A 国打算选择一座或多座城市（**至少一座**），并在这些城市上各建造一座军营。\n\n众所周知，军营之间的联络是十分重要的。然而此时 A 国接到情报，B 国将会于不久后袭击 A 国的一条道路，但具体的袭击目标却无从得知。如果 B 国袭击成功，这条道路将被切断，可能会造成 A 国某两个军营无法互相到达，这是 A 国极力避免的。因此 A 国决定派兵看守若干条道路（**可以是一条或多条，也可以一条也不看守**），A 国有信心保证被派兵看守的道路能够抵御 B 国的袭击而不被切断。\n\nA 国希望制定一个建造军营和看守道路的方案，使得 B 国袭击的无论是 A 国的哪条道路，都不会造成某两座军营无法互相到达。现在，请你帮 A 国计算一下可能的建造军营和看守道路的方案数共有多少。由于方案数可能会很多，你只需要输出其对 $1,000,000,007\\left(10^{9}+7\\right)$ 取模的值即可。两个方案被认为是不同的，当且仅当存在至少一座城市在一个方案中建造了军营而在另一个方案中没有，或者存在至少一条道路在一个方案中被派兵看守而在另一个方案中没有。\n\n## 输入格式\n\n第一行包含两个正整数 $n,m$，分别表示城市的个数和双向道路的数量。\n\n接下来 $m$ 行，每行包含两个正整数 $u_{i},v_{i}$，描述一条连接 $u_{i}$ 和 $v_{i}$ 的双向道路。保证没有重边和自环。\n\n## 输出格式\n\n输出一行包含一个整数，表示建造军营和看守道路的方案数对 $1,000,000,007\\left(10^{9}+ 7\\right)$ 取模的结果。\n\n## 输入输出样例 #1\n\n### 输入 #1\n\n```\n2 1\n1 2\n```\n\n### 输出 #1\n\n```\n5\n```\n\n## 输入输出样例 #2\n\n### 输入 #2\n\n```\n4 4\n1 2\n2 3\n3 1\n1 4\n```\n\n### 输出 #2\n\n```\n184\n```\n\n## 输入输出样例 #3\n\n### 输入 #3\n\n```\n见附加文件里的 barrack/barrack3.in\n```\n\n### 输出 #3\n\n```\n见附加文件里的 barrack/barrack3.ans\n```\n\n## 输入输出样例 #4\n\n### 输入 #4\n\n```\n见附加文件里的 barrack/barrack4.in\n```\n\n### 输出 #4\n\n```\n见附加文件里的 barrack/barrack4.ans\n```\n\n## 说明/提示\n\n### 样例 1 解释\n\n样例中，A 国共有两座城市，有 $1$ 条道路连接他们。\n\n所有可能的方案如下：\n\n- 在城市 $1$ 建军营，不看守这条道路；\n- 在城市 $1$ 建军营，看守这条道路；\n- 在城市 $2$ 建军营，不看守这条道路；\n- 在城市 $2$ 建军营，看守这条道路；\n- 在城市 $1,2$ 建军营，看守这条道路。\n\n### 数据规模与约定\n\n对于所有数据，保证 $1 \\leq n \\leq 5 \\times 10^5$，$n - 1 \\leq m \\leq 10^6$，$1 \\leq u_i, v_i \\leq n$，$u_i \\neq v_i$。\n\n::cute-table{tuack}\n\n|测试点编号 | $n \\leq $ | $m \\leq $| 特殊条件 |\n| :-: | :-: | :-: | :-: |\n| $1 \\sim 3$ | $8$ | $10$ | 无 |\n| $4 \\sim 7$ | $16$ | $25$ | ^ |\n| $8 \\sim 9$ | $3000$ | $5000$ | ^ |\n| $10 \\sim 11$ | $5 \\times 10^5$ | $10^6$ | 特殊性质 $\\mathrm{A}$ |\n| $12 \\sim 14$ | ^ | ^ | $m = n - 1$ |\n| $15 \\sim 16$ | ^ | ^ | $m = n$ |\n| $17 \\sim 20$ | ^ | ^ | 无 |\n\n特殊性质 $\\mathrm{A}$：保证 $m=n-1$ 且第 $i$ 条道路连接城市 $i$ 与 $i+1$。\n\n## 解题思路\n首先，如果一条边断开后可能导致图不再连通，则该边需要考虑是否必须守卫，否则守卫或不守卫任意。故只需要考虑割边即可。\n先用 Tarjan 求出所有割边，然后按删除所有割边后的连通分量缩点并建树，这样每条边都是原先的割边。\n每个点有建或不建两种情况，每条非割边可任选看守或不看守，如果两个连通分量中都有被选择的军营则路径上割边都要被看守，否则任意选。\n\n为了统计答案，我们使用树形 DP。设 $f_{0,u}$ 表示子树 $u$ 中无军营的方案数，$f_{1,u}$ 表示子树 $u$ 中有军营且 $u$ 父节点处有军营的方案数。\n设 $P=\\prod_{v \\in son(u)} (2f_{0,v}+f_{1,v}),Q=\\prod_{v \\in son(u)} (2f_{0,v})$。\n对于 $f_{0,u}$，其方案数是子树都空乘上每条边是否选择，故 $f_{0,u}=Q$。\n对于 $f_{1,u}$，设 $sz_u$ 表示连通块 $u$ 内节点数，则每条边在子树被选择时必须被看守，否则都可选择。同时要减去全空方案，故 $f_{1,u}=2^{sz_u} \\times P -Q$。\n\n最后统计答案，设 $ans_u$ 为 $u$ 为子树最高点的答案。\n显然 $f_{1,u}$ 是合法的，然而其中可能存在 $u$ 不是最高点，即 $u$ 为空而只有一个子树内点被选情况，\n对于每个 $v$ 发生这种情况的方案数为 $f_{1,v} \\times \\prod_{w \\in son(u),w \\ne v} f_{0,w}= \\frac{f_{1,v}}{2f_{0,v}}$，为了去重需要减掉这部分。\n同时外部割边可任意选，设 $O=\\sum_{v \\in son(u)} \\frac{f_{1,v}}{2f_{0,v}}$，$szt_u$ 为 $u$ 内割边数，$dlb$ 为总割边数，则 $ans_u=2^{dlb-szt_u+1} (f_{1,u}-O)$。\n最后累加答案并乘上非割边选择情况 $2^{m-dlb}$ 即可。\n\n## 代码\n\n```cpp\n#include <bits/stdc++.h>\nusing namespace std;\n#define int long long\n#define PII pair<int,int>\n#define fi first\n#define se second\n#define pb push_back\nconst int N=5e5+10,M=1e6+10,V=5e6+10,mod=1e9+7;\nint dfn[N],low[N],idx,tot,res,dlb,ltk[N],ans[N],p2[V],f1[N],f0[N],c[N],szt[N];\nbool vis[N],hvd[M],hvx[M];\nvector<PII> G1[N],scc;\nvector<int> G2[N];\nint ksm(int a,int b,int p){\n\tint res=1;\n    a%=p;\n\twhile(b){\n\t\tif(b&1) res=res*a%p;\n\t\ta=a*a%p;\n\t\tb>>=1;\n\t}\n\treturn res%p;\n}\nvoid tarjan(int u,int fa,int b){\n\tlow[u]=dfn[u]=++idx;\n\tvis[u]=true;\n\tfor(auto v:G1[u]){\n\t\tif(v.fi==fa) continue;\n\t\tif(vis[v.fi]) low[u]=min(low[u],dfn[v.fi]);\n\t\telse{\n\t\t\ttarjan(v.fi,u,v.se);\n\t\t\tlow[u]=min(low[u],low[v.fi]);\n\t\t}\n\t}\n\tif(fa&&low[u]>dfn[fa]){\n\t\thvd[b]=true;\n\t\tdlb++;\n\t}\n}\nint dfs0(int x){\n\tint sz=1;\n\tvis[x]=true;\n\tltk[x]=idx;\n\tfor(auto i:G1[x]){\n\t\tif(hvd[i.se]){\n\t\t\tif(ltk[i.fi]&&ltk[i.fi]!=idx){\n\t\t\t\tG2[idx].pb(ltk[i.fi]);\n\t\t\t\tG2[ltk[i.fi]].pb(idx);\n\t\t\t}\n\t\t\tcontinue;\n\t\t}\n\t\tif(!hvx[i.se]){\n\t\t\ttot++;\n\t\t\thvx[i.se]=true;\n\t\t}\n\t\tif(!vis[i.fi]){\n\t\t\tsz+=dfs0(i.fi);\n\t\t}\n\t}\n\treturn sz;\n}\nvoid dfs2(int x,int fa){\n\tint p=1,q=1,o=0;\n\tszt[x]=1;\n\tfor(auto i:G2[x]){\n\t\tif(i==fa) continue;\n\t\tdfs2(i,x);\n\t\tszt[x]+=szt[i];\n\t\tq=q*2*f0[i]%mod;\n\t\tp=(2*f0[i]%mod+f1[i]%mod)%mod*p%mod;\n\t}\n\tf0[x]=q;f1[x]=(p2[scc[x].fi]*p%mod-q%mod+mod)%mod;\n\tfor(auto i:G2[x]){\n\t\tif(i==fa) continue;\n\t\to=(f1[i]%mod*ksm(2*f0[i],mod-2,mod)%mod+o%mod)%mod;\n\t}\n\to=o*q%mod;\n\tc[x]=(f1[x]%mod-o%mod+mod)%mod;\n\tif(fa) c[x]=c[x]*p2[dlb-szt[x]+1]%mod;\n}\nsigned main(){\n\tios::sync_with_stdio(0);\n\tcin.tie(0);cout.tie(0);\n\tint n,m;cin>>n>>m;\n\tp2[0]=1;\n\tfor(int i=1;i<=(n+m)*3;i++){\n\t\tp2[i]=(p2[i-1]<<1)%mod;\n\t}\n\tfor(int i=1;i<=m;i++){\n\t\tint u,v;cin>>u>>v;\n\t\tG1[u].pb({v,i});G1[v].pb({u,i});\n\t}\n\ttarjan(1,0,0);\n\tmemset(vis,false,sizeof vis);\n\tidx=0;\n\tscc.pb({0,0});\n\tfor(int i=1;i<=n;i++){\n\t\tif(!vis[i]){\n\t\t\tidx++;\n\t\t\tint z=dfs0(i);\n\t\t\tscc.pb({z,tot});\n\t\t\ttot=0;\n\t\t}\n\t}\n\tdfs2(1,0);\n\tfor(int i=1;i<(int)scc.size();i++){\n\t\tres=(res%mod+c[i]%mod)%mod;\n\t}\n\tres=res*p2[m-dlb]%mod;\n\tcout<<res%mod;\n\treturn 0;\n}\n```\n",
  "category": "图论",
  "tags": [
    "Tarjan",
    "割边",
    "缩点",
    "树形DP",
    "NOIP"
  ],
  "kind": "problem",
  "difficulty": "提高+/省选−",
  "relations": [],
  "parent_key": null
}
$json$::jsonb) as result_sub_admin_p8867_barrack;

